use chrono::Local;
use clap::Parser;
use regex::Regex;
use serde::{Deserialize, Serialize};
use std::collections::VecDeque;
use std::fs::{File, OpenOptions};
use std::io::{BufWriter, Write};
use std::process::{Command, Stdio};
use std::time::{Duration, Instant};
use std::thread;
use std::sync::{Arc, Mutex};

#[derive(Parser, Debug)]
#[command(
    name = "hwatch",
    version = "0.3.19",
    about = "A modern alternative to the watch command, records the differences in execution results and can check this differences at after.",
    long_about = None
)]
struct Args {
    /// command to run
    #[arg(trailing_var_arg = true, allow_hyphen_values = true)]
    command: Vec<String>,

    /// output execution results to stdout
    #[arg(short, long)]
    batch: bool,

