use std::io::{BufWriter, Write};
use std::process::{Command, Stdio};
use std::time::{Duration, Instant};
use std::thread;
use std::sync::{Arc, Mutex};

#[derive(Parser, Debug)]
#[command(
    name = "hwatch",
    version = "0.3.19",
    about = "A modern alternative to the watch command, records the differences in execution results and can check this differences at after.",
    long_about = None
)]
struct Args {
    /// command to run
    #[arg(trailing_var_arg = true, allow_hyphen_values = true)]
    command: Vec<String>,

    /// output execution results to stdout
    #[arg(short, long)]
    batch: bool,

    /// beep if command has a change result
    #[arg(short = 'B', long)]
    beep: bool,

    /// Surround each pane with a border frame
    #[arg(long)]
    border: bool,

    /// When the border option is enabled, display scrollbar on the right side of watch pane.
    #[arg(long)]
    with_scrollbar: bool,

    /// enable mouse wheel support
    #[arg(long)]
    mouse: bool,

    /// interpret ANSI color and style sequences
    #[arg(short, long)]
    color: bool,

    /// display text upside down
    #[arg(short, long)]
    reverse: bool,

    /// Compress data in memory
    #[arg(short = 'C', long)]
    compress: bool,

    /// hide the UI on start
    #[arg(short, long)]
    no_title: bool,

    /// collect character-level diff count in summary
    #[arg(long)]
    enable_summary_char: bool,

    /// show line number
    #[arg(short = 'N', long)]
    line_number: bool,

    /// hide the "Display help with h key" message
    #[arg(long)]
    no_help_banner: bool,

    /// disable the calculation for summary
    #[arg(long)]
    no_summary: bool,

    /// Run the command directly, not through the shell
    #[arg(short = 'x', long)]
    exec: bool,

    /// Display only the lines with differences during line diff and word diff
    #[arg(short = 'O', long)]
    diff_output_only: bool,

    /// Executes the specified command if the output changes
    #[arg(short = 'A', long)]
    aftercommand: Option<String>,

    /// logging file
    #[arg(short, long)]
    logfile: Option<Option<String>>,

    /// shell to use at runtime
    #[arg(short = 's', long, default_value = "sh -c")]
    shell: String,

    /// seconds to wait between updates
    #[arg(short, long, default_value = "2")]
    interval: f64,

    /// Attempt to run as close to the interval as possible
    #[arg(long)]
    precise: bool,

    /// Set the number of history records to keep
    #[arg(short = 'L', long, default_value = "5000")]
    limit: usize,

    /// Specifying tab display size
    #[arg(long, default_value = "4")]
    tab_size: usize,

    /// highlight changes between updates
    #[arg(short = 'd', long)]
    differences: Option<Option<String>>,

    /// Select command output
    #[arg(short, long, default_value = "output")]
    output: String,

    /// Add keymap
    #[arg(short = 'K', long)]
    keymap: Option<String>,
}

#[derive(Debug, Serialize, Deserialize, Clone)]
struct ExecutionRecord {
    timestamp: String,
    command: String,
    status: bool,
    output: String,
    stdout: String,
    stderr: String,
}

impl Default for ExecutionRecord {
    fn default() -> Self {
        Self {
            timestamp: String::new(),
            command: String::new(),
            status: true,
            output: String::new(),
            stdout: String::new(),
            stderr: String::new(),
        }
    }
}

struct WatchState {
    history: VecDeque<ExecutionRecord>,
    last_output: String,
    log_file: Option<BufWriter<File>>,
    limit: usize,
}

impl WatchState {
    fn new(limit: usize, logfile: Option<&str>) -> Result<Self> {
        let mut state = WatchState {
            history: VecDeque::new(),
            last_output: String::new(),
            log_file: None,
            limit,
        };

        // Try to read existing log file
        if let Some(logfile_path) = logfile {
            if std::path::Path::new(logfile_path).exists() {
                if let Ok(content) = std::fs::read_to_string(logfile_path) {
                    for line in content.lines() {
                        if !line.is_empty() {
                            if let Ok(record) = serde_json::from_str::<ExecutionRecord>(line) {
                                if !record.timestamp.is_empty() {
                                    state.history.push_back(record);
                                    if state.history.len() > limit {
                                        state.history.pop_front();
                                    }
                                }
                            }
                        }
                    }
                }
            }

            let file = OpenOptions::new()
                .create(true)
                .append(true)
                .open(logfile_path)?;
            state.log_file = Some(BufWriter::new(file));
        }

        Ok(state)
    }

    fn record_execution(&mut self, record: ExecutionRecord) -> Result<()> {
        self.history.push_back(record.clone());
        if self.history.len() > self.limit {
            self.history.pop_front();
        }

        if let Some(ref mut writer) = self.log_file {
            writeln!(writer, "{}", serde_json::to_string(&record)?)?;
            writer.flush()?;
        }

        Ok(())
    }
}

fn execute_command(args: &Args) -> Result<ExecutionRecord> {
    let now = Local::now();
    let timestamp = now.format("%Y-%m-%d %H:%M:%S%.3f").to_string();

    let output = if args.exec {
        // Direct execution without shell
        if args.command.is_empty() {
            return Err(anyhow::anyhow!("No command specified"));
        }

        let mut cmd = Command::new(&args.command[0]);
        if args.command.len() > 1 {
            cmd.args(&args.command[1..]);
        }
        cmd.output()?
    } else {
        // Shell execution
        let cmd_string = args.command.join(" ");
        let shell_parts: Vec<&str> = args.shell.split_whitespace().collect();

        let mut cmd = if shell_parts.is_empty() {
            Command::new("sh")
        } else {
            Command::new(shell_parts[0])
        };

        for part in &shell_parts[1..] {
            cmd.arg(part);
        }

        // Handle {COMMAND} placeholder
        let mut final_cmd_string = args.shell.clone();
        if let Some(pos) = final_cmd_string.find("{COMMAND}") {
            final_cmd_string.replace_range(pos..pos + 9, &cmd_string);
        } else if args.shell == "sh -c" || args.shell == "bash -c" {
            cmd.arg(&cmd_string);
        } else {
            cmd.arg(&cmd_string);
        }

        let mut cmd = if shell_parts.is_empty() {
            Command::new("sh")
        } else {
            Command::new(shell_parts[0])
        };

        for part in &shell_parts[1..] {
            cmd.arg(part);
        }
        cmd.arg(&cmd_string);

        cmd.output()?
    };

    let stdout = String::from_utf8_lossy(&output.stdout).to_string();
    let stderr = String::from_utf8_lossy(&output.stderr).to_string();
    let combined = format!("{}{}", stdout, stderr);

    Ok(ExecutionRecord {
        timestamp,
        command: args.command.join(" "),
        status: output.status.success(),
        output: combined.clone(),
        stdout,
        stderr,
    })
}

fn format_timestamp_line(timestamp: &str) -> String {
    let line = format!("=====[{}]=========================", timestamp);
    format!("\x1b[38;5;240m{}\x1b[0m", line)
}

fn apply_watch_diff(old: &str, new: &str) -> String {
    let old_lines: Vec<&str> = old.lines().collect();
    let new_lines: Vec<&str> = new.lines().collect();

    let mut result = String::new();
    for (i, &line) in new_lines.iter().enumerate() {
        if i >= old_lines.len() || old_lines[i] != line {
            // Mark entire line as changed
            for c in line.chars() {
                result.push_str("\x1b[7m");
                result.push(c);
                result.push_str("\x1b[7m");
            }
            result.push_str("\x1b[0m");
        } else {
            result.push_str(line);
        }
        result.push('\n');
    }

    result
}

fn apply_line_diff(old: &str, new: &str) -> String {
    let old_lines: Vec<&str> = old.lines().collect();
    let new_lines: Vec<&str> = new.lines().collect();

    let mut result = String::new();
    let mut max_lines = old_lines.len().max(new_lines.len());

    for i in 0..max_lines {
        let old_line = old_lines.get(i).copied().unwrap_or("");
        let new_line = new_lines.get(i).copied().unwrap_or("");

        if old_line != new_line {
            result.push_str("\x1b[7m");
            result.push_str(new_line);
            result.push_str("\x1b[0m");
        } else {
            result.push_str(new_line);
        }
        if i < max_lines - 1 {
            result.push('\n');
        }
    }

    result
}

fn apply_word_diff(old: &str, new: &str) -> String {
    let old_words: Vec<&str> = old.split_whitespace().collect();
    let new_words: Vec<&str> = new.split_whitespace().collect();

    let mut result = String::new();
    let mut word_idx = 0;

    for new_word in new_words {
        if word_idx >= old_words.len() || old_words[word_idx] != new_word {
            result.push_str("\x1b[7m");
            result.push_str(new_word);
            result.push_str("\x1b[0m");
        } else {
            result.push_str(new_word);
        }
        result.push(' ');
        word_idx += 1;
    }

    result.trim_end().to_string()
}

#[tokio::main]
async fn main() -> Result<()> {
    let args = Args::parse();

    if args.command.is_empty() {
        eprintln!("Error: command is required");
        std::process::exit(1);
    }

    let mut state = WatchState::new(args.limit, args.logfile.as_ref().and_then(|x| x.as_ref()).map(|s| s.as_str()))?;

    let interval_dur = Duration::from_secs_f64(args.interval);

    if args.batch {
        // Batch mode - just output execution results to stdout
        loop {
            let start = Instant::now();

            match execute_command(&args) {
                Ok(record) => {
                    let output = &record.output;

                    println!("{}", format_timestamp_line(&record.timestamp));

                    match args.differences.as_ref().and_then(|x| x.as_ref()).map(|s| s.as_str()) {
                        Some("watch") => {
                            if !state.last_output.is_empty() {
                                let diff = apply_watch_diff(&state.last_output, output);
                                print!("{}", diff);
                            } else {
                                print!("{}", output);
                            }
                        }
                        Some("line") => {
                            if !state.last_output.is_empty() {
                                let diff = apply_line_diff(&state.last_output, output);
                                print!("{}", diff);
                            } else {
                                print!("{}", output);
                            }
                        }
                        Some("word") => {
                            if !state.last_output.is_empty() {
                                let diff = apply_word_diff(&state.last_output, output);
                                print!("{}", diff);
                            } else {
                                print!("{}", output);
                            }
                        }
                        _ => {
                            print!("{}", output);
                        }
                    }

                    if !output.ends_with('\n') {
                        println!();
                    }
                    println!();

                    state.last_output = output.clone();
                    state.record_execution(record)?;
                }
                Err(e) => {
                    eprintln!("Error executing command: {}", e);
                }
            }

            let elapsed = start.elapsed();
            if elapsed < interval_dur {
                thread::sleep(interval_dur - elapsed);
            }
        }
    } else {
        // TUI mode - for now, we'll implement a basic version
        eprintln!("TUI mode not yet implemented in this basic version");
        std::process::exit(1);
    }
}
