impl WatchState {
    fn new(limit: usize, logfile: Option<&str>) -> io::Result<Self> {
        let mut state = WatchState {
            history: VecDeque::new(),
            last_output: String::new(),
            log_file: None,
            limit,
        };

        // Try to read existing log file
        if let Some(logfile_path) = logfile {
            if std::path::Path::new(logfile_path).exists() {
                if let Ok(content) = std::fs::read_to_string(logfile_path) {
                    for line in content.lines() {
                        if !line.is_empty() {
                            if let Ok(record) = parse_json_record(line) {
                                if !record.timestamp.is_empty() {
                                    state.history.push_back(record);
                                    if state.history.len() > limit {
                                        state.history.pop_front();
                                    }
                                }
                            }
                        }
                    }
                }
            }

            let file = OpenOptions::new()
                .create(true)
                .append(true)
                .open(logfile_path)?;
            state.log_file = Some(BufWriter::new(file));
        }

        Ok(state)
    }

    fn record_execution(&mut self, record: ExecutionRecord) -> io::Result<()> {
        self.history.push_back(record.clone());
        if self.history.len() > self.limit {
            self.history.pop_front();
        }

        if let Some(ref mut writer) = self.log_file {
            let json = record_to_json(&record);
            writeln!(writer, "{}", json)?;
