fn parse_json_record(line: &str) -> Result<ExecutionRecord, Box<dyn std::error::Error>> {
    // Simple JSON parser for our record
    let mut record = ExecutionRecord::default();

    if let Some(start) = line.find("\"timestamp\":\"") {
        if let Some(end) = line[start + 13..].find('"') {
            record.timestamp = line[start + 13..start + 13 + end].to_string();
        }
    }

    if let Some(start) = line.find("\"command\":\"") {
        if let Some(end) = line[start + 11..].find('"') {
            record.command = line[start + 11..start + 11 + end].to_string();
        }
    }

    if let Some(start) = line.find("\"status\":") {
        if line[start + 9..].starts_with("true") {
            record.status = true;
        } else {
            record.status = false;
        }
    }

    // For output, stdout, stderr - we'll do basic extraction
    if let Some(start) = line.find("\"output\":\"") {
        if let Some(end) = line[start + 10..].rfind('"') {
            record.output = line[start + 10..start + 10 + end].to_string();
            record.output = unescape_string(&record.output);
        }
    }

    if let Some(start) = line.find("\"stdout\":\"") {
        if let Some(end) = line[start + 10..].rfind('"') {
