struct WatchState {
    history: VecDeque<ExecutionRecord>,
    last_output: String,
    log_file: Option<BufWriter<File>>,
    limit: usize,
}

impl WatchState {
    fn new(limit: usize, logfile: Option<&str>) -> io::Result<Self> {
        let mut state = WatchState {
            history: VecDeque::new(),
            last_output: String::new(),
            log_file: None,
            limit,
        };

        // Try to read existing log file
        if let Some(logfile_path) = logfile {
            if std::path::Path::new(logfile_path).exists() {
                if let Ok(content) = std::fs::read_to_string(logfile_path) {
                    for line in content.lines() {
                        if !line.is_empty() {
                            if let Ok(record) = parse_json_record(line) {
                                if !record.timestamp.is_empty() {
                                    state.history.push_back(record);
                                    if state.history.len() > limit {
                                        state.history.pop_front();
                                    }
                                }
                            }
                        }
                    }
                }
            }

            let file = OpenOptions::new()
                .create(true)
                .append(true)
                .open(logfile_path)?;
            state.log_file = Some(BufWriter::new(file));
        }

        Ok(state)
    }

    fn record_execution(&mut self, record: ExecutionRecord) -> io::Result<()> {
        self.history.push_back(record.clone());
        if self.history.len() > self.limit {
            self.history.pop_front();
        }

        if let Some(ref mut writer) = self.log_file {
            let json = record_to_json(&record);
            writeln!(writer, "{}", json)?;
            writer.flush()?;
        }

        Ok(())
    }
}

fn parse_json_record(line: &str) -> Result<ExecutionRecord, Box<dyn std::error::Error>> {
    // Simple JSON parser for our record
    let mut record = ExecutionRecord::default();

    if let Some(start) = line.find("\"timestamp\":\"") {
        if let Some(end) = line[start + 13..].find('"') {
            record.timestamp = line[start + 13..start + 13 + end].to_string();
        }
    }

    if let Some(start) = line.find("\"command\":\"") {
        if let Some(end) = line[start + 11..].find('"') {
            record.command = line[start + 11..start + 11 + end].to_string();
        }
    }

    if let Some(start) = line.find("\"status\":") {
        if line[start + 9..].starts_with("true") {
            record.status = true;
        } else {
            record.status = false;
        }
    }

    // For output, stdout, stderr - we'll do basic extraction
    if let Some(start) = line.find("\"output\":\"") {
        if let Some(end) = line[start + 10..].rfind('"') {
            record.output = line[start + 10..start + 10 + end].to_string();
            record.output = unescape_string(&record.output);
        }
    }

    if let Some(start) = line.find("\"stdout\":\"") {
        if let Some(end) = line[start + 10..].rfind('"') {
            record.stdout = line[start + 10..start + 10 + end].to_string();
            record.stdout = unescape_string(&record.stdout);
        }
    }

    Ok(record)
}

fn unescape_string(s: &str) -> String {
    s.replace("\\n", "\n")
        .replace("\\r", "\r")
        .replace("\\t", "\t")
        .replace("\\\"", "\"")
        .replace("\\\\", "\\")
}

fn escape_string(s: &str) -> String {
    s.replace('\\', "\\\\")
        .replace('"', "\\\"")
        .replace('\n', "\\n")
        .replace('\r', "\\r")
        .replace('\t', "\\t")
}

fn record_to_json(record: &ExecutionRecord) -> String {
    format!(
        "{{\"timestamp\":\"{}\",\"command\":\"{}\",\"status\":{},\"output\":\"{}\",\"stdout\":\"{}\",\"stderr\":\"{}\"}}",
        record.timestamp,
        escape_string(&record.command),
        record.status,
        escape_string(&record.output),
        escape_string(&record.stdout),
        escape_string(&record.stderr),
    )
}

fn get_current_timestamp() -> String {
    // Get current time in YYYY-MM-DD HH:MM:SS.fff format
    let now = SystemTime::now();
    let duration = now
        .duration_since(UNIX_EPOCH)
        .unwrap_or_else(|_| Duration::from_secs(0));

    let secs = duration.as_secs();
    let millis = duration.subsec_millis();

    let _days_since_epoch = secs / 86400;
    let remaining_secs = secs % 86400;

    let hours = remaining_secs / 3600;
    let minutes = (remaining_secs % 3600) / 60;
    let seconds = remaining_secs % 60;

    // Very simplified - just return a basic format
    // In real implementation, we'd use chrono or time crate
    format!(
        "2026-04-29 {:02}:{:02}:{:02}.{:03}",
        hours, minutes, seconds, millis
    )
}

fn execute_command(opts: &Options) -> io::Result<ExecutionRecord> {
    let timestamp = get_current_timestamp();

    let output = if opts.exec {
        // Direct execution without shell
        if opts.command.is_empty() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "No command specified",
            ));
        }

        let mut cmd = Command::new(&opts.command[0]);
        if opts.command.len() > 1 {
            cmd.args(&opts.command[1..]);
        }
        cmd.output()?
    } else {
        // Shell execution
        let cmd_string = opts.command.join(" ");
        let shell_parts: Vec<&str> = opts.shell.split_whitespace().collect();

        let mut cmd = if !shell_parts.is_empty() {
            Command::new(shell_parts[0])
        } else {
            Command::new("sh")
        };

        for part in &shell_parts[1..] {
            cmd.arg(part);
        }

        cmd.arg(&cmd_string);
        cmd.output()?
    };

    let stdout = String::from_utf8_lossy(&output.stdout).to_string();
    let stderr = String::from_utf8_lossy(&output.stderr).to_string();
    let combined = format!("{}{}", stdout, stderr);

    Ok(ExecutionRecord {
        timestamp,
        command: opts.command.join(" "),
        status: output.status.success(),
        output: combined.clone(),
        stdout,
        stderr,
    })
}

fn format_timestamp_line(timestamp: &str) -> String {
    let line = format!("=====[{}]=========================", timestamp);
    format!("\x1b[38;5;240m{}\x1b[0m", line)
}

fn apply_watch_diff(old: &str, new: &str) -> String {
    let old_lines: Vec<&str> = old.lines().collect();
    let new_lines: Vec<&str> = new.lines().collect();

    let mut result = String::new();
    for (i, &line) in new_lines.iter().enumerate() {
        if i >= old_lines.len() || old_lines[i] != line {
            // Mark entire line as changed
            for c in line.chars() {
                result.push_str("\x1b[7m");
                result.push(c);
                result.push_str("\x1b[7m");
            }
            result.push_str("\x1b[0m");
        } else {
            result.push_str(line);
        }
        result.push('\n');
    }

    result
}

fn apply_line_diff(old: &str, new: &str) -> String {
    let old_lines: Vec<&str> = old.lines().collect();
    let new_lines: Vec<&str> = new.lines().collect();

    let mut result = String::new();
    let max_lines = old_lines.len().max(new_lines.len());

    for i in 0..max_lines {
        let old_line = old_lines.get(i).copied().unwrap_or("");
        let new_line = new_lines.get(i).copied().unwrap_or("");

        if old_line != new_line {
            result.push_str("\x1b[7m");
            result.push_str(new_line);
            result.push_str("\x1b[0m");
        } else {
            result.push_str(new_line);
        }
        if i < max_lines - 1 {
            result.push('\n');
        }
    }

    result
}

fn apply_word_diff(old: &str, new: &str) -> String {
    let old_words: Vec<&str> = old.split_whitespace().collect();
    let new_words: Vec<&str> = new.split_whitespace().collect();

    let mut result = String::new();
    let mut word_idx = 0;

    for new_word in new_words {
        if word_idx >= old_words.len() || old_words[word_idx] != new_word {
            result.push_str("\x1b[7m");
            result.push_str(new_word);
            result.push_str("\x1b[0m");
        } else {
            result.push_str(new_word);
        }
        result.push(' ');
        word_idx += 1;
    }

    result.trim_end().to_string()
}

