fn main() {
    let opts = parse_args();

    if opts.command.is_empty() {
        eprintln!("Error: command is required");
        std::process::exit(1);
    }

    match WatchState::new(opts.limit, opts.logfile.as_ref().map(|s| s.as_str())) {
        Ok(mut state) => {
            let interval_dur = Duration::from_secs_f64(opts.interval);

            if opts.batch {
                // Batch mode - just output execution results to stdout
                loop {
                    let start = Instant::now();

                    match execute_command(&opts) {
                        Ok(record) => {
                            let output = &record.output;

                            println!("{}", format_timestamp_line(&record.timestamp));

                            match opts.differences.as_ref().map(|s| s.as_str()) {
                                Some("watch") => {
                                    if !state.last_output.is_empty() {
                                        let diff = apply_watch_diff(&state.last_output, output);
                                        print!("{}", diff);
                                    } else {
                                        print!("{}", output);
                                    }
                                }
                                Some("line") => {
                                    if !state.last_output.is_empty() {
                                        let diff = apply_line_diff(&state.last_output, output);
                                        print!("{}", diff);
                                    } else {
                                        print!("{}", output);
                                    }
                                }
                                Some("word") => {
                                    if !state.last_output.is_empty() {
                                        let diff = apply_word_diff(&state.last_output, output);
                                        print!("{}", diff);
                                    } else {
                                        print!("{}", output);
                                    }
                                }
                                _ => {
                                    print!("{}", output);
                                }
                            }

                            if !output.ends_with('\n') {
                                println!();
                            }
                            println!();

                            state.last_output = output.clone();
                            let _ = state.record_execution(record);
                        }
                        Err(e) => {
                            eprintln!("Error executing command: {}", e);
                        }
                    }

                    let elapsed = start.elapsed();
                    if elapsed < interval_dur {
                        thread::sleep(interval_dur - elapsed);
                    }
                }
            } else {
                // TUI mode - for now, we'll error out
                eprintln!("TUI mode not yet implemented in this basic version");
                std::process::exit(1);
            }
        }
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    }
}
