                            if let Ok(record) = parse_json_record(line) {
                                if !record.timestamp.is_empty() {
                                    state.history.push_back(record);
                                    if state.history.len() > limit {
                                        state.history.pop_front();
                                    }
                                }
                            }
                        }
                    }
                }
            }

            let file = OpenOptions::new()
                .create(true)
                .append(true)
                .open(logfile_path)?;
            let mut writer = BufWriter::new(file);

            // Write empty template record first (like the original)
            let template = ExecutionRecord::default();
            let json = record_to_json(&template);
            writeln!(writer, "{}", json)?;
            writer.flush()?;

