            stdout: String::new(),
            stderr: String::new(),
        }
    }
}

#[derive(Debug, Clone)]
struct Options {
    command: Vec<String>,
    batch: bool,
    beep: bool,
    border: bool,
    with_scrollbar: bool,
    mouse: bool,
    color: bool,
    reverse: bool,
    compress: bool,
    no_title: bool,
    enable_summary_char: bool,
    line_number: bool,
    no_help_banner: bool,
    no_summary: bool,
    exec: bool,
    diff_output_only: bool,
    aftercommand: Option<String>,
    logfile: Option<String>,
    shell: String,
    interval: f64,
    precise: bool,
    limit: usize,
    tab_size: usize,
    differences: Option<String>,
    output_mode: String,
    keymap: Option<String>,
}

impl Default for Options {
    fn default() -> Self {
        Self {
            command: Vec::new(),
            batch: false,
            beep: false,
            border: false,
            with_scrollbar: false,
            mouse: false,
            color: false,
            reverse: false,
            compress: false,
            no_title: false,
            enable_summary_char: false,
            line_number: false,
            no_help_banner: false,
            no_summary: false,
            exec: false,
            diff_output_only: false,
            aftercommand: None,
            logfile: None,
            shell: "sh -c".to_string(),
            interval: 2.0,
            precise: false,
            limit: 5000,
            tab_size: 4,
            differences: None,
            output_mode: "output".to_string(),
            keymap: None,
        }
    }
}

struct WatchState {
    history: VecDeque<ExecutionRecord>,
    last_output: String,
    log_file: Option<BufWriter<File>>,
    limit: usize,
}

impl WatchState {
    fn new(limit: usize, logfile: Option<&str>) -> io::Result<Self> {
        let mut state = WatchState {
            history: VecDeque::new(),
            last_output: String::new(),
            log_file: None,
            limit,
        };

        // Try to read existing log file
        if let Some(logfile_path) = logfile {
            if std::path::Path::new(logfile_path).exists() {
                if let Ok(content) = std::fs::read_to_string(logfile_path) {
                    for line in content.lines() {
                        if !line.is_empty() {
                            if let Ok(record) = parse_json_record(line) {
                                if !record.timestamp.is_empty() {
                                    state.history.push_back(record);
                                    if state.history.len() > limit {
                                        state.history.pop_front();
                                    }
                                }
                            }
                        }
                    }
                }
            }

            let file = OpenOptions::new()
                .create(true)
                .append(true)
                .open(logfile_path)?;
            let mut writer = BufWriter::new(file);

            // Write empty template record first (like the original)
            let template = ExecutionRecord::default();
            let json = record_to_json(&template);
            writeln!(writer, "{}", json)?;
            writer.flush()?;

            state.log_file = Some(writer);
        }

        Ok(state)
    }

    fn record_execution(&mut self, record: ExecutionRecord) -> io::Result<()> {
        self.history.push_back(record.clone());
        if self.history.len() > self.limit {
            self.history.pop_front();
        }

        if let Some(ref mut writer) = self.log_file {
            let json = record_to_json(&record);
            writeln!(writer, "{}", json)?;
            writer.flush()?;
        }

        Ok(())
    }
}

fn parse_json_record(line: &str) -> Result<ExecutionRecord, Box<dyn std::error::Error>> {
    // Simple JSON parser for our record
    let mut record = ExecutionRecord::default();

    if let Some(start) = line.find("\"timestamp\":\"") {
        if let Some(end) = line[start + 13..].find('"') {
            record.timestamp = line[start + 13..start + 13 + end].to_string();
        }
    }

    if let Some(start) = line.find("\"command\":\"") {
        if let Some(end) = line[start + 11..].find('"') {
            record.command = line[start + 11..start + 11 + end].to_string();
        }
    }

    if let Some(start) = line.find("\"status\":") {
        if line[start + 9..].starts_with("true") {
            record.status = true;
        } else {
            record.status = false;
        }
    }

    // For output, stdout, stderr - we'll do basic extraction
    if let Some(start) = line.find("\"output\":\"") {
        if let Some(end) = line[start + 10..].rfind('"') {
            record.output = line[start + 10..start + 10 + end].to_string();
            record.output = unescape_string(&record.output);
        }
    }

    if let Some(start) = line.find("\"stdout\":\"") {
        if let Some(end) = line[start + 10..].rfind('"') {
            record.stdout = line[start + 10..start + 10 + end].to_string();
            record.stdout = unescape_string(&record.stdout);
        }
    }

    Ok(record)
}

fn unescape_string(s: &str) -> String {
    s.replace("\\n", "\n")
        .replace("\\r", "\r")
        .replace("\\t", "\t")
        .replace("\\\"", "\"")
        .replace("\\\\", "\\")
}

fn escape_string(s: &str) -> String {
    s.replace('\\', "\\\\")
        .replace('"', "\\\"")
        .replace('\n', "\\n")
        .replace('\r', "\\r")
        .replace('\t', "\\t")
}

fn record_to_json(record: &ExecutionRecord) -> String {
    format!(
        "{{\"timestamp\":\"{}\",\"command\":\"{}\",\"status\":{},\"output\":\"{}\",\"stdout\":\"{}\",\"stderr\":\"{}\"}}",
        record.timestamp,
        escape_string(&record.command),
        record.status,
        escape_string(&record.output),
        escape_string(&record.stdout),
        escape_string(&record.stderr),
    )
}

fn get_current_timestamp() -> String {
    // Get current time in YYYY-MM-DD HH:MM:SS.fff format
    let now = SystemTime::now();
    let duration = now
        .duration_since(UNIX_EPOCH)
        .unwrap_or_else(|_| Duration::from_secs(0));

    let secs = duration.as_secs();
    let millis = duration.subsec_millis();

    let _days_since_epoch = secs / 86400;
    let remaining_secs = secs % 86400;

    let hours = remaining_secs / 3600;
    let minutes = (remaining_secs % 3600) / 60;
    let seconds = remaining_secs % 60;

    // Very simplified - just return a basic format
    // In real implementation, we'd use chrono or time crate
    format!(
        "2026-04-29 {:02}:{:02}:{:02}.{:03}",
        hours, minutes, seconds, millis
    )
}

fn execute_command(opts: &Options) -> io::Result<ExecutionRecord> {
    let timestamp = get_current_timestamp();

    let output = if opts.exec {
        // Direct execution without shell
        if opts.command.is_empty() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "No command specified",
            ));
        }

        let mut cmd = Command::new(&opts.command[0]);
        if opts.command.len() > 1 {
            cmd.args(&opts.command[1..]);
        }
        cmd.output()?
    } else {
        // Shell execution
        let cmd_string = opts.command.join(" ");
        let shell_parts: Vec<&str> = opts.shell.split_whitespace().collect();

        let mut cmd = if !shell_parts.is_empty() {
            Command::new(shell_parts[0])
        } else {
            Command::new("sh")
        };

        for part in &shell_parts[1..] {
            cmd.arg(part);
        }

        cmd.arg(&cmd_string);
        cmd.output()?
    };

    let stdout = String::from_utf8_lossy(&output.stdout).to_string();
    let stderr = String::from_utf8_lossy(&output.stderr).to_string();
    let combined = format!("{}{}", stdout, stderr);

    Ok(ExecutionRecord {
        timestamp,
        command: opts.command.join(" "),
        status: output.status.success(),
        output: combined.clone(),
        stdout,
        stderr,
    })
}

fn format_timestamp_line(timestamp: &str) -> String {
    let line = format!("=====[{}]=========================", timestamp);
    format!("\x1b[38;5;240m{}\x1b[0m", line)
}

fn apply_watch_diff(old: &str, new: &str) -> String {
    let old_lines: Vec<&str> = old.lines().collect();
    let new_lines: Vec<&str> = new.lines().collect();

    let mut result = String::new();
    for (i, &line) in new_lines.iter().enumerate() {
        if i >= old_lines.len() || old_lines[i] != line {
            // Mark entire line as changed
            for c in line.chars() {
                result.push_str("\x1b[7m");
                result.push(c);
                result.push_str("\x1b[7m");
            }
            result.push_str("\x1b[0m");
        } else {
            result.push_str(line);
        }
        result.push('\n');
    }

    result
}

fn apply_line_diff(old: &str, new: &str) -> String {
    let old_lines: Vec<&str> = old.lines().collect();
    let new_lines: Vec<&str> = new.lines().collect();

    let mut result = String::new();
    let max_lines = old_lines.len().max(new_lines.len());

    for i in 0..max_lines {
        let old_line = old_lines.get(i).copied().unwrap_or("");
        let new_line = new_lines.get(i).copied().unwrap_or("");

        if old_line != new_line {
            result.push_str("\x1b[7m");
            result.push_str(new_line);
            result.push_str("\x1b[0m");
        } else {
            result.push_str(new_line);
        }
        if i < max_lines - 1 {
            result.push('\n');
        }
    }

    result
}

fn apply_word_diff(old: &str, new: &str) -> String {
    let old_words: Vec<&str> = old.split_whitespace().collect();
    let new_words: Vec<&str> = new.split_whitespace().collect();

    let mut result = String::new();
    let mut word_idx = 0;

    for new_word in new_words {
        if word_idx >= old_words.len() || old_words[word_idx] != new_word {
            result.push_str("\x1b[7m");
            result.push_str(new_word);
            result.push_str("\x1b[0m");
        } else {
            result.push_str(new_word);
        }
        result.push(' ');
        word_idx += 1;
    }

    result.trim_end().to_string()
}

fn parse_args() -> Options {
    let args: Vec<String> = env::args().collect();
    let mut opts = Options::default();
    let mut i = 1;

    while i < args.len() {
        match args[i].as_str() {
            "-h" | "--help" => {
                print_help();
                std::process::exit(0);
            }
            "-V" | "--version" => {
                println!("hwatch 0.3.19");
                std::process::exit(0);
            }
            "-b" | "--batch" => {
                opts.batch = true;
                i += 1;
            }
            "-B" | "--beep" => {
                opts.beep = true;
                i += 1;
            }
            "--border" => {
                opts.border = true;
                i += 1;
            }
            "--with-scrollbar" => {
                opts.with_scrollbar = true;
                i += 1;
            }
            "--mouse" => {
                opts.mouse = true;
                i += 1;
            }
            "-c" | "--color" => {
                opts.color = true;
                i += 1;
            }
            "-r" | "--reverse" => {
                opts.reverse = true;
                i += 1;
            }
            "-C" | "--compress" => {
                opts.compress = true;
                i += 1;
            }
            "-t" | "--no-title" => {
                opts.no_title = true;
                i += 1;
            }
            "--enable-summary-char" => {
                opts.enable_summary_char = true;
                i += 1;
            }
            "-N" | "--line-number" => {
                opts.line_number = true;
                i += 1;
            }
            "--no-help-banner" => {
                opts.no_help_banner = true;
                i += 1;
            }
            "--no-summary" => {
                opts.no_summary = true;
                i += 1;
            }
            "-x" | "--exec" => {
                opts.exec = true;
                i += 1;
            }
            "-O" | "--diff-output-only" => {
                opts.diff_output_only = true;
                i += 1;
            }
            "-A" | "--aftercommand" => {
                i += 1;
                if i < args.len() {
                    opts.aftercommand = Some(args[i].clone());
                    i += 1;
                }
            }
            "-l" | "--logfile" => {
                i += 1;
                if i < args.len() {
                    opts.logfile = Some(args[i].clone());
                    i += 1;
                }
            }
            "-s" | "--shell" => {
                i += 1;
                if i < args.len() {
                    opts.shell = args[i].clone();
                    i += 1;
                }
            }
            "-n" | "--interval" => {
                i += 1;
                if i < args.len() {
                    opts.interval = args[i].parse().unwrap_or(2.0);
                    i += 1;
                }
            }
            "--precise" => {
                opts.precise = true;
                i += 1;
            }
            "-L" | "--limit" => {
                i += 1;
                if i < args.len() {
                    opts.limit = args[i].parse().unwrap_or(5000);
                    i += 1;
                }
            }
            "--tab-size" => {
                i += 1;
                if i < args.len() {
                    opts.tab_size = args[i].parse().unwrap_or(4);
                    i += 1;
                }
            }
            "-d" | "--differences" => {
                i += 1;
                if i < args.len() && !args[i].starts_with('-') {
                    opts.differences = Some(args[i].clone());
                    i += 1;
                } else {
                    opts.differences = Some("watch".to_string());
                }
            }
            "-o" | "--output" => {
                i += 1;
                if i < args.len() {
                    opts.output_mode = args[i].clone();
                    i += 1;
                }
            }
            "-K" | "--keymap" => {
                i += 1;
                if i < args.len() {
                    opts.keymap = Some(args[i].clone());
                    i += 1;
                }
            }
            _ => {
                // Everything else is the command
                opts.command = args[i..].to_vec();
                break;
            }
        }
    }

    opts
}

fn print_help() {
    let help_text = "A modern alternative to the watch command, records the differences in execution results and can check this differences at after.

Usage: executable [OPTIONS] [command]...

Arguments:
  [command]...  

Options:
  -b, --batch                         output execution results to stdout
  -B, --beep                          beep if command has a change result
      --border                        Surround each pane with a border frame
      --with-scrollbar                When the border option is enabled, display scrollbar on the right side of watch pane.
      --mouse                         enable mouse wheel support. With this option, copying text with your terminal may be harder. Try holding the Shift key.
  -c, --color                         interpret ANSI color and style sequences
  -r, --reverse                       display text upside down.
  -C, --compress                      Compress data in memory. Note: If the output of the command is small, you may not get the desired effect.
  -t, --no-title                      hide the UI on start. Use `t` to toggle it.
      --enable-summary-char           collect character-level diff count in summary.
  -N, --line-number                   show line number
      --no-help-banner                hide the \"Display help with h key\" message
      --no-summary                    disable the calculation for summary that is running behind the scenes, and disable the summary function in the first place.
  -x, --exec                          Run the command directly, not through the shell. Much like the `-x` option of the watch command.
  -O, --diff-output-only              Display only the lines with differences during `line` diff and `word` diff.
  -A, --aftercommand <after_command>  Executes the specified command if the output changes. Information about changes is stored in json format in environment variable ${HWATCH_DATA}.
  -l, --logfile [<logfile>]           logging file. if a log file is already used, its contents will be read and executed.
  -s, --shell <shell_command>         shell to use at runtime. can also insert the command to the location specified by {COMMAND}. [default: \"sh -c\"]
  -n, --interval <interval>           seconds to wait between updates [default: 2]
      --precise                       Attempt to run as close to the interval as possible, regardless of how long the command takes to run
  -L, --limit <limit>                 Set the number of history records to keep. only work in watch mode. Set `0` for unlimited recording. (default: 5000) [default: 5000]
      --tab-size <tab_size>           Specifying tab display size [default: 4]
  -d, --differences [<differences>]   highlight changes between updates [possible values: none, watch, line, word]
  -o, --output [<output>]             Select command output. [default: output] [possible values: output, stdout, stderr]
  -K, --keymap <keymap>               Add keymap
  -h, --help                          Print help
  -V, --version                       Print version";
    println!("{}", help_text);
}

fn main() {
    let opts = parse_args();

    if opts.command.is_empty() {
        eprintln!("Error: command is required");
        std::process::exit(1);
    }

    match WatchState::new(opts.limit, opts.logfile.as_ref().map(|s| s.as_str())) {
        Ok(mut state) => {
            let interval_dur = Duration::from_secs_f64(opts.interval);

            if opts.batch {
                // Batch mode - just output execution results to stdout
                loop {
                    let start = Instant::now();

                    match execute_command(&opts) {
                        Ok(record) => {
                            let output = &record.output;

                            println!("{}", format_timestamp_line(&record.timestamp));

                            match opts.differences.as_ref().map(|s| s.as_str()) {
                                Some("watch") => {
                                    if !state.last_output.is_empty() {
                                        let diff = apply_watch_diff(&state.last_output, output);
                                        print!("{}", diff);
                                    } else {
                                        print!("{}", output);
                                    }
                                }
                                Some("line") => {
                                    if !state.last_output.is_empty() {
                                        let diff = apply_line_diff(&state.last_output, output);
                                        print!("{}", diff);
                                    } else {
                                        print!("{}", output);
                                    }
                                }
                                Some("word") => {
                                    if !state.last_output.is_empty() {
                                        let diff = apply_word_diff(&state.last_output, output);
                                        print!("{}", diff);
                                    } else {
                                        print!("{}", output);
                                    }
                                }
                                _ => {
                                    print!("{}", output);
                                }
                            }

                            if !output.ends_with('\n') {
                                println!();
                            }
                            println!();

                            state.last_output = output.clone();
                            let _ = state.record_execution(record);
                        }
                        Err(e) => {
                            eprintln!("Error executing command: {}", e);
                        }
                    }

                    let elapsed = start.elapsed();
                    if elapsed < interval_dur {
                        thread::sleep(interval_dur - elapsed);
                    }
                }
            } else {
                // TUI mode - for now, we'll error out
                eprintln!("TUI mode not yet implemented in this basic version");
                std::process::exit(1);
            }
        }
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    }
}
